-- Christian Ethics final module. Run seed_ethics_course.sql first. Safe to run more than once.

do $seed$
declare cid uuid;
begin
  select id into cid from public.courses where slug = 'christian-ethics';
  if cid is null then raise exception 'Run the course file first'; end if;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 4, $j$Final Assessment: My Christian Ethics Portfolio$j$, $j${"prompt": "Create a Christian Ethics portfolio of at least 600 words and prepare a short presentation of its main ideas. Use complete sentences and label each part. Do not name real private individuals or share private details. Micah 6:8 says, He hath shewed thee, O man, what is good; and what doth the LORD require of thee, but to do justly, and to love mercy, and to walk humbly with thy God?\n\nPart 1: Foundation. Explain why Christians believe right and wrong rest on the character of God and the authority of Scripture, and explain the role of conscience.\nPart 2: The great commandments. Explain the two great commandments and how the Ten Commandments apply to a modern situation.\nPart 3: Character. Choose three fruit of the Spirit and write a plan to grow each through daily habits.\nPart 4: Case study one. Describe a school or home situation involving honesty, purity, money or anger. Apply the DECIDE style steps: identify the problem, list options, test each by Scripture and love for neighbor, and choose the best response.\nPart 5: Case study two. Describe a situation involving justice, technology or artificial intelligence. Explain what Scripture teaches and how a Christian should act.\nPart 6: Other views. Compare one other way of thinking about right and wrong with the Christian view, with strengths and weaknesses, fairly and respectfully.\nPart 7: Service. Plan one act of service or witness for your church or community and tell how you will speak with gentleness.\nPart 8: Faith and reflection. Apply at least three Scriptures from the King James Version to your portfolio and explain what you learned and your next step.\nPart 9: Presentation plan. List five main points you would share in a three minute talk.", "rubric": "100 points. Part 1: 10 points. Part 2: 10 points. Part 3: 10 points. Part 4: 15 points. Part 5: 15 points. Part 6: 10 points. Part 7: 5 points. Part 8: 10 points. Part 9: 5 points. Grammar, conventions and respectful tone: 10 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Final Assessment: My Christian Ethics Portfolio$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 16, $j$Final Exam: Christian Ethics$j$, $j${"questions": [{"q": "Christian ethics asks first:", "options": ["What does God require?", "What is popular?", "What is easy?", "What is profitable?"]}, {"q": "People have dignity because they are made:", "options": ["By wealth", "By chance", "By law", "In the image of God"]}, {"q": "Conscience should be:", "options": ["Trained by Scripture and the Holy Spirit", "Ignored", "Always trusted without question", "Silenced"]}, {"q": "Jesus summed up the law as love for God and:", "options": ["Love for rules", "Love for money", "Love for success", "Love for neighbor"]}, {"q": "The fruit of the Spirit is listed in:", "options": ["Psalm 1", "Genesis 1", "Acts 1", "Galatians 5"]}, {"q": "Relativism says right and wrong:", "options": ["Come only from God", "Do not matter", "Never change", "Depend on a person or culture"]}, {"q": "Plagiarism is:", "options": ["Presenting another person's work as your own", "Studying", "Editing", "Giving credit"]}, {"q": "Ephesians 4:15 says to speak the truth:", "options": ["Only when angry", "In love", "Never", "To win arguments"]}, {"q": "1 Corinthians 6:19 calls the body:", "options": ["A trophy", "Unimportant", "A tool for money", "The temple of the Holy Ghost"]}, {"q": "Stewardship means:", "options": ["Owning everything", "Managing what belongs to God", "Avoiding work", "Wasting resources"]}, {"q": "Ephesians 4:32 teaches us to be:", "options": ["Careless", "Kind and forgiving", "Angry and proud", "Silent and cold"]}, {"q": "Acts 17:26 says God made all nations of:", "options": ["Many origins", "One blood", "Soldiers", "Kings"]}, {"q": "An ethical rule for using artificial intelligence in schoolwork is to:", "options": ["Copy it without reading", "Trust every answer", "Follow school rules, check answers and give credit", "Hide that you used it"]}, {"q": "Acts 5:29 applies when a law:", "options": ["Requires sin", "Is unpopular", "Is new", "Is inconvenient"]}, {"q": "James 1:22 says to be:", "options": ["Doers of the word", "Hearers only", "Critics only", "Silent"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Final Exam: Christian Ethics$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,3,0,3,3,3,0,1,3,1,1,1,2,0,0}'::int[], array[$j$God's will is the starting point.$j$,$j$Genesis 1:27.$j$,$j$A trained conscience guides well.$j$,$j$Matthew 22:37 to 39.$j$,$j$Galatians 5:22 and 23.$j$,$j$Relativism denies a universal standard.$j$,$j$It is dishonest.$j$,$j$Truth and love belong together.$j$,$j$Our bodies belong to God.$j$,$j$We manage on God's behalf.$j$,$j$Forgive as God forgave in Christ.$j$,$j$All people share one human family.$j$,$j$Honesty and verification matter.$j$,$j$Obey God rather than men only when commanded to sin.$j$,$j$Faith must be lived.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Final Exam: Christian Ethics$j$ on conflict (item_id) do nothing;
end
$seed$;
